schemas.schema-01-systematic.prisma:
/// Master table for all store sections/sub-stores within the platform.
/// Represents logical or branded subdivisions of the shopping mall,
/// organizing products and categories per business, brand, or special
/// segment. Critical for multi-store environments, this model establishes
/// the backbone for product and category mapping, as well as for access
/// control and customization. Related to {@link shopping_mall_ai_channels}
/// and {@link shopping_mall_ai_channel_categories} via foreign keys or
/// mappings.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_sections {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Display name of the section/sub-store (e.g., 'Fashion Plaza', 'Brand X
  /// Outlet').
  name String

  /// Business-unique, immutable code identifier for the section (e.g.,
  /// 'FASHION_PLAZA'). Used for administration, mapping, and reference in
  /// other tables. Must be unique across all sections.
  code String

  /// Detailed description and business purpose of the section. Used for
  /// administration and display. Optional for some sections.
  description String?

  /// Whether this section is currently enabled and visible to platform users.
  /// Controls store appearance and admin access.
  is_active Boolean

  /// Sort/display priority for front-end listing and backoffice UI. Lower
  /// values show earlier; ties broken by name.
  display_order Int @db.Integer

  /// Timestamp of section creation (for auditing and lifecycle management).
  created_at DateTime @db.Timestamptz

  /// Timestamp of last update to section data.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the section was (soft) deleted; nullable for active
  /// records.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  shopping_mall_ai_product_channel_maps shopping_mall_ai_product_channel_maps[]
  shopping_mall_ai_discount_rules shopping_mall_ai_discount_rules[]

  @@unique([code])
  @@index([is_active])
  @@index([display_order])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Master table for business channels (sales, affiliate, event, or
/// brand-specific), forming top-level logical groupings for catalog and
/// transaction flows. Channels define eligibility, business rules, region,
/// or promotional context (e.g., 'Main', 'Mobile', 'Partner_A'). Many
/// platform processes and products are mapped per channel. Related to {@link
/// shopping_mall_ai_channel_categories} and {@link
/// shopping_mall_ai_channel_category_maps}.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_channels {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Business display name of the channel. Typically used by frontend and
  /// admin. Examples: 'Main Channel', 'Mobile Exclusive'.
  name String

  /// Unique channel code. Immutable, used for business process mapping (e.g.,
  /// 'MAIN', 'MOBILE', 'PARTNER_A').
  code String

  /// Long-form description or notes for the channel's business scope,
  /// restrictions, or target audience.
  description String?

  /// Optional code for regional segmentation or country grouping (e.g., 'KR',
  /// 'US', 'ASIA'). Null if global.
  region_code String?

  /// Whether this channel is currently active and available for operations,
  /// mapping, or display.
  is_active Boolean

  /// Order in which the channel appears on lists or in backoffice config;
  /// lower values have higher priority.
  display_order Int @db.Integer

  /// Timestamp of channel creation.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for this channel/model.
  updated_at DateTime @db.Timestamptz

  /// Soft-deletion timestamp if channel is removed from platform offering.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  shopping_mall_ai_channel_categories shopping_mall_ai_channel_categories[]
  shopping_mall_ai_product_channel_maps shopping_mall_ai_product_channel_maps[]
  shopping_mall_ai_discount_rules shopping_mall_ai_discount_rules[]

  @@unique([code])
  @@index([is_active])
  @@index([display_order])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Master table for categories which exist within the context of a
/// particular sales channel. Enables per-channel category definitions,
/// business policies, and display layouts. This decouples global categories
/// from channel-specific ones, allowing for localized or customized category
/// trees. Used throughout admin and front system for navigation, search, and
/// product mapping. Mapped via {@link
/// shopping_mall_ai_channel_category_maps}.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_channel_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent channel's {@link shopping_mall_ai_channels.id}. Category only
  /// visible in this channel context.
  shopping_mall_ai_channel_id String @db.Uuid

  /// Human-friendly display name for the category as presented in this channel
  /// context.
  name String

  /// Unique code for this category in the channel context. Used for mapping,
  /// lookup, and business rules.
  code String

  /// (Nullable) Self-reference for hierarchical category trees. Null if root.
  /// Points to {@link shopping_mall_ai_channel_categories.id}.
  parent_id String? @db.Uuid

  /// Sort/display priority in category trees/tabs/menus within a channel.
  /// Lower = higher up.
  display_order Int @db.Integer

  /// Optional long-form text describing the category, policy, or intended
  /// product domain.
  description String?

  /// Whether this category is active in platform navigation and product
  /// assignment.
  is_active Boolean

  /// Creation timestamp for tracking and audit.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for data lifecycle management.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion marker for business-side purging or audit only.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  channel shopping_mall_ai_channels @relation(fields: [shopping_mall_ai_channel_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_channel_categories_shopping_mall_ai_c_602c4f4c")

  shopping_mall_ai_channel_category_maps shopping_mall_ai_channel_category_maps[]

  @@unique([shopping_mall_ai_channel_id, code], map: "shopping_mall_ai_channel_categories_shopping_mall_ai_c_d6b7a980")
  @@index([shopping_mall_ai_channel_id, display_order], map: "shopping_mall_ai_channel_categories_shopping_mall_ai_c_b16070db")
  @@index([is_active])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Junction table mapping channel-specific categories to global categories
/// in the system (which exist in another component as
/// shopping_mall_ai_categories). This enables complex mapping of platform-,
/// channel-, or locale-level category trees, while maintaining independence
/// from global changes. Maintains referential integrity to both local
/// (channel category) and global category models. Used heavily in admin
/// mapping workflows and in search/category navigation. No business
/// fields—purely mapping.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_channel_category_maps {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Target channel category's {@link shopping_mall_ai_channel_categories.id}.
  shopping_mall_ai_channel_category_id String @db.Uuid

  /// Target global category's {@link shopping_mall_ai_categories.id} (external
  /// component - foreign reference only).
  shopping_mall_ai_category_id String @db.Uuid

  /// Creation timestamp of this mapping (for auditing/ref, not for business
  /// display).
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  channelCategory shopping_mall_ai_channel_categories @relation(fields: [shopping_mall_ai_channel_category_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_channel_category_maps_shopping_mall_a_760bb63b")
  category shopping_mall_ai_categories @relation(fields: [shopping_mall_ai_category_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_channel_category_maps_shopping_mall_a_d14b616c")

  @@index([shopping_mall_ai_category_id], map: "shopping_mall_ai_channel_category_maps_shopping_mall_a_3ea93ba9")

  @@unique([shopping_mall_ai_channel_category_id, shopping_mall_ai_category_id], map: "shopping_mall_ai_channel_category_maps_shopping_mall_a_6b9f07b7")
}

/// System-level configuration and master option codes table. Stores
/// key-value pairs and hierarchical configuration settings for cross-domain
/// control. Used for toggles (e.g., feature flags), system-wide limits,
/// business rules, or display texts. Central authority for all reference
/// options (not business domain data). Keys are unique per component-scope
/// (e.g., SYSTEM, PRODUCT, ORDER).
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_configurations {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Type or functional domain of the configuration (e.g., 'SYSTEM',
  /// 'PRODUCT', 'ORDER', 'CHANNEL', application area, etc.). Used for grouping
  /// config sets and enforcing option scoping. Must be indexed for fast
  /// scoping lookup.
  scope String

  /// Config option code (e.g., 'DEFAULT_CURRENCY', 'INVITE_ENABLED'). Unique
  /// per scope. Drives feature flags, master data, or parameter assignment.
  key String

  /// String-encoded configuration value. Holds the effective parameter,
  /// toggle, or default for the option context. Decoded by services/UI per
  /// config key type.
  value String

  /// Optional description of the configuration item—business logic, impact,
  /// range of values, or operational notes.
  description String?

  /// Whether this option is currently active. Used to phase in/out major
  /// config elements or setup automated rules.
  is_active Boolean

  /// Creation timestamp for config/audit purposes.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp in config lifecycle.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp if config is logically removed from live scope.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([scope, key])
  @@index([scope])
  @@index([key(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-02-identity.prisma:
/// Represents individual customers registered on the shoppingMallAi
/// platform. This model tracks customer-specific credentials, contact
/// information, verification status, authentication details, and account
/// lifecycle (active, suspended, withdrawn). It supports the full customer
/// registration, authentication, profile management, and permission
/// enforcement lifecycle. Directly subject to strict business and legal
/// compliance for identity information. No overlap with seller or
/// administrator information.
///
/// @namespace Identity
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_customers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer's email address. Used for login, notification, and unique
  /// identity enforcement. Must be unique among all customers and verified
  /// during registration. Business rule: cannot be null.
  email String

  /// Customer's mobile phone number. Used for account recovery, 2FA, and
  /// notifications. May be required for certain operations. Business rule:
  /// optional in registration, but required for some features.
  mobile String?

  /// BCrypt or Argon2 encoded password hash for authentication. Only for
  /// internal login; not set for OAuth/SSO-only accounts. Never exposed to
  /// client applications.
  password_hash String

  /// OAuth or SSO provider identifier if registered via external login. Null
  /// for local/password accounts.
  oauth_provider String?

  /// External provider's account ID, if any. Null for password-auth accounts.
  provider_account_id String?

  /// Customer display nickname or handle. May be changed by user subject to
  /// business rules and length/policy constraints.
  nickname String

  /// Whether the customer's email is verified. Used to determine eligibility
  /// for most actions beyond browsing.
  is_email_verified Boolean

  /// Whether the customer's mobile is verified. Required for certain business
  /// actions.
  is_mobile_verified Boolean

  /// Customer account status. Enum: 'active', 'pending', 'suspended',
  /// 'withdrawn', 'banned'. Business logic controls access per status.
  status String

  /// Last successful login timestamp for session and security tracking.
  last_login_at DateTime? @db.Timestamptz

  /// Timestamp when the customer account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the customer account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the account was logically deleted (withdrawn). Null if
  /// active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  shopping_mall_ai_carts shopping_mall_ai_carts[]
  shopping_mall_ai_cart_merge_logs shopping_mall_ai_cart_merge_logs[]
  shopping_mall_ai_orders shopping_mall_ai_orders[]
  shopping_mall_ai_order_state_logs shopping_mall_ai_order_state_logs[]
  shopping_mall_ai_returns shopping_mall_ai_returns[]
  shopping_mall_ai_after_service_requests shopping_mall_ai_after_service_requests[]
  shopping_mall_ai_coupon_issuance_logs shopping_mall_ai_coupon_issuance_logs[]
  shopping_mall_ai_coupon_redemption_logs shopping_mall_ai_coupon_redemption_logs[]
  shopping_mall_ai_deposit_accounts shopping_mall_ai_deposit_accounts?
  shopping_mall_ai_mileage_accounts shopping_mall_ai_mileage_accounts?
  shopping_mall_ai_financial_audit_logs shopping_mall_ai_financial_audit_logs[]
  shopping_mall_ai_reviews shopping_mall_ai_reviews[]
  shopping_mall_ai_review_snapshots shopping_mall_ai_review_snapshots[]
  shopping_mall_ai_inquiries shopping_mall_ai_inquiries[]
  shopping_mall_ai_inquiry_snapshots shopping_mall_ai_inquiry_snapshots[]
  shopping_mall_ai_comments shopping_mall_ai_comments[]
  shopping_mall_ai_comment_snapshots shopping_mall_ai_comment_snapshots[]
  shopping_mall_ai_ai_reco_signals shopping_mall_ai_ai_reco_signals[]
  shopping_mall_ai_ai_personalization_profiles shopping_mall_ai_ai_personalization_profiles?
  shopping_mall_ai_ai_analytics_exposures shopping_mall_ai_ai_analytics_exposures[]
  shopping_mall_ai_fraud_logs shopping_mall_ai_fraud_logs[]
  shopping_mall_ai_incident_logs shopping_mall_ai_incident_logs[]
  shopping_mall_ai_audit_trails shopping_mall_ai_audit_trails[]

  @@unique([email])
  @@unique([nickname])
  @@index([status])
  @@index([created_at])
  @@index([nickname(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Represents business sellers on the shoppingMallAi platform. Tracks seller
/// credentials, business registration, account lifecycle, and verification
/// status. Only unique to sellers, disjoint from customers/administrators.
/// Includes identity, contact, compliance, and verification workflow
/// management. Every seller must be approved by an administrator prior to
/// making transactions.
///
/// @namespace Identity
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_sellers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Seller's email address. Used for login, notifications, and identity. Must
  /// be unique among sellers.
  email String

  /// Seller's mobile or business contact number. Used for
  /// authentication/notification. Optional on initial application, may be
  /// required for further business actions.
  mobile String?

  /// Public display name of the seller's business/channel. May differ from
  /// internal legal name.
  display_name String

  /// Password hash for login (BCrypt/Argon2). Not set if only using OAuth/SSO.
  password_hash String

  /// OAuth or SSO provider name, if registered externally. Null for
  /// password-based.
  oauth_provider String?

  /// Provider-side identity value, if OAuth/SSO is used.
  provider_account_id String?

  /// Legal company or business name registered for compliance/audit. Required
  /// for verification.
  business_name String

  /// Official business registration ID as required by law. Must be unique
  /// among all sellers.
  business_registration_number String

  /// Seller's designated bank account for settlements and remittances. May be
  /// required only after verification.
  bank_account_number String?

  /// Seller account status. Enum: 'active', 'pending', 'suspended',
  /// 'withdrawn', 'banned'. Controls permissions/business actions.
  status String

  /// Whether the seller has passed admin/kyc verification and is permitted to
  /// transact.
  is_verified Boolean

  /// Timestamp when seller requested verification. Aids in SLA enforcement.
  verification_requested_at DateTime? @db.Timestamptz

  /// Timestamp when verification completed. Null until verified.
  verified_at DateTime? @db.Timestamptz

  /// Timestamp when seller account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when seller account last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when seller withdrew or was removed. Null if account is active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  shopping_mall_ai_products shopping_mall_ai_products[]
  shopping_mall_ai_product_bundles shopping_mall_ai_product_bundles[]
  shopping_mall_ai_orders shopping_mall_ai_orders[]
  shopping_mall_ai_order_suborders shopping_mall_ai_order_suborders[]
  shopping_mall_ai_order_state_logs shopping_mall_ai_order_state_logs[]
  shopping_mall_ai_after_service_requests shopping_mall_ai_after_service_requests[]
  shopping_mall_ai_coupons shopping_mall_ai_coupons[]
  shopping_mall_ai_discount_campaigns shopping_mall_ai_discount_campaigns[]
  shopping_mall_ai_financial_audit_logs shopping_mall_ai_financial_audit_logs[]
  shopping_mall_ai_inquiries shopping_mall_ai_inquiries[]
  shopping_mall_ai_inquiry_snapshots shopping_mall_ai_inquiry_snapshots[]
  shopping_mall_ai_comments shopping_mall_ai_comments[]
  shopping_mall_ai_comment_snapshots shopping_mall_ai_comment_snapshots[]

  @@unique([email])
  @@unique([business_registration_number])
  @@index([display_name])
  @@index([status])
  @@index([display_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Platform superusers and operators with system-wide access and oversight.
/// Used for internal access (not buyers/sellers). Tracks admin credentials,
/// policy role/authorization, status, and audit fields. Must be strictly
/// separated from business/seller/customer records for compliance and legal
/// defensibility.
///
/// @namespace Identity
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_administrators {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Administrator email. Used for login and notification. Unique among all
  /// administrators.
  email String

  /// Hashed password for login with elevated security (may enforce stricter
  /// policy than other roles).
  password_hash String

  /// Administrator's display name for audit and access logs. May not be legal
  /// name, but identifies the admin in history.
  display_name String

  /// Administrator account status. Enum: 'active', 'suspended', 'withdrawn',
  /// 'banned'. Determines access to system.
  status String

  /// Administrator authorization and role level. E.g., 'superadmin',
  /// 'reviewer', 'support', as per business policy.
  role String

  /// Last login timestamp for tracking admin access activity.
  last_login_at DateTime? @db.Timestamptz

  /// Timestamp when administrator account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when administrator account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when account was withdrawn/removed. Null if still active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  shopping_mall_ai_product_snapshots shopping_mall_ai_product_snapshots[]
  shopping_mall_ai_order_state_logs shopping_mall_ai_order_state_logs[]
  shopping_mall_ai_coupons shopping_mall_ai_coupons[]
  shopping_mall_ai_discount_campaigns shopping_mall_ai_discount_campaigns[]
  shopping_mall_ai_financial_audit_logs shopping_mall_ai_financial_audit_logs[]
  shopping_mall_ai_comments shopping_mall_ai_comments[]
  shopping_mall_ai_comment_snapshots shopping_mall_ai_comment_snapshots[]
  shopping_mall_ai_moderation_logs shopping_mall_ai_moderation_logs[]

  @@unique([email])
  @@index([display_name])
  @@index([role])
  @@index([display_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-03-catalog.prisma:
/// All main products listed on the shoppingMallAi platform. Each record
/// represents a base product as provided by a seller, including title, core
/// attributes, pricing baseline, and lifecycle state. Serves as the
/// canonical object for variants, option sets, and is referenced in bundles,
/// category mapping, channel mapping, and snapshot tables. Product state
/// changes are versioned via {@link shopping_mall_ai_product_snapshots}.
///
/// @namespace Catalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_products {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged seller's {@link shopping_mall_ai_sellers.id}. Owning entity
  /// responsible for product management, inventory, and listing compliance.
  shopping_mall_ai_seller_id String @db.Uuid

  /// Unique product business code as assigned by seller/platform. Used for
  /// deduplication, search, and integration with external systems. Must be
  /// unique among this seller's products.
  code String

  /// Public product name. Required for all products. Displayed in listing and
  /// search results.
  title String

  /// Detailed product description (long text, possibly rich content).
  description String

  /// Product origin (e.g., 'Korea', 'Imported', etc.). For compliance,
  /// logistics, and search filtering.
  origin String

  /// Product brand name, if applicable. Supports brand-specific filtering and
  /// compliance.
  brand String

  /// Base price in platform currency for standard configuration of this
  /// product.
  default_price Float @db.DoublePrecision

  /// Whether the product is currently published (listed and visible to buyers).
  published Boolean

  /// Workflow state of product: 'draft', 'pending', 'approved', 'rejected',
  /// 'archived'. Per business rule, governs visibility and modification
  /// rights.
  approval_status String

  /// Entity creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Most recent update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Timestamp for soft deletion. Null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  seller shopping_mall_ai_sellers @relation(fields: [shopping_mall_ai_seller_id], references: [id], onDelete: Cascade)

  shopping_mall_ai_product_variants shopping_mall_ai_product_variants[]
  shopping_mall_ai_product_options shopping_mall_ai_product_options[]
  shopping_mall_ai_product_bundle_items shopping_mall_ai_product_bundle_items[]
  shopping_mall_ai_product_snapshots shopping_mall_ai_product_snapshots[]
  shopping_mall_ai_product_category_maps shopping_mall_ai_product_category_maps[]
  shopping_mall_ai_product_channel_maps shopping_mall_ai_product_channel_maps[]
  shopping_mall_ai_cart_items shopping_mall_ai_cart_items[]
  shopping_mall_ai_order_items shopping_mall_ai_order_items[]
  shopping_mall_ai_discount_rules shopping_mall_ai_discount_rules[]
  shopping_mall_ai_reviews shopping_mall_ai_reviews[]
  shopping_mall_ai_inquiries shopping_mall_ai_inquiries[]
  shopping_mall_ai_ai_reco_signals shopping_mall_ai_ai_reco_signals[]
  shopping_mall_ai_ai_price_optimizations shopping_mall_ai_ai_price_optimizations[]

  @@unique([shopping_mall_ai_seller_id, code])
  @@index([shopping_mall_ai_seller_id])
  @@index([published, approval_status])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Variants of a product, such as size or color combinations, representing
/// actual sellable SKUs. Connects to main product entry and option sets.
/// Each variant represents a unique physical goods with independent
/// inventory and price override.
///
/// @namespace Catalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_product_variants {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged product's {@link shopping_mall_ai_products.id}. References the
  /// base product this variant is attached to.
  shopping_mall_ai_product_id String @db.Uuid

  /// Stock Keeping Unit: unique business identifier for this variant.
  sku String

  /// Serialized description of option combination (e.g.,
