schemas.schema-06-discounts.prisma:
/// Core business table representing all platform and seller-issued coupons.
/// Defines coupon metadata, scope, state, issuance/redeem conditions, quota,
/// source campaign, stackability policy, and issuance controls. Tied to
/// issuance/redemption logs and parent campaigns. Supports both
/// product-level and cart-level discount logic. Links to campaign and
/// optionally a seller or platform administrator. Follows snapshot and
/// compliance/auditing patterns. Used extensively in coupon event flows.
///
/// @namespace Discounts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_coupons {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Source discount campaign's {@link
  /// shopping_mall_ai_discount_campaigns.id}. References the campaign that
  /// originated this coupon.
  shopping_mall_ai_discount_campaign_id String? @db.Uuid

  /// Coupon's issuing seller's {@link shopping_mall_ai_sellers.id}. Nullable
  /// if platform-wide or administrator coupon.
  shopping_mall_ai_seller_id String? @db.Uuid

  /// Coupon's issuing administrator's {@link
  /// shopping_mall_ai_administrators.id}. Nullable if seller coupon.
  shopping_mall_ai_administrator_id String? @db.Uuid

  /// Coupon code (unique per platform or per campaign, used for redemption).
  code String

  /// Coupon display title/purpose (e.g. Spring Sale 10%).
  title String

  /// Detailed description of the coupon offer or campaign.
  description String?

  /// Type of coupon (fixed, percent, free_shipping) for platform logic.
  /// Limited to allowed enums in business logic.
  type String

  /// Scope of coupon applicability (e.g., product, category, cart-wide).
  scope String

  /// Current state: issued, active, suspended, expired, redeemed, revoked,
  /// deleted. Life-cycle management for backend enforcement.
  status String

  /// Total number of coupon codes issued. Used for quota and tracking.
  issued_quantity Int @db.Integer

  /// Redemption quota per unique user. Used for eligibility checks.
  issued_per_user_quota Int @db.Integer

  /// Number of times this coupon has been redeemed. For quota and abuse
  /// monitoring.
  redeemed_quantity Int @db.Integer

  /// Cap (if any) on discount value this coupon can grant. Applies to
  /// percent/fixed.
  max_discount_amount Float? @db.DoublePrecision

  /// Minimum order value for coupon applicability.
  minimum_purchase_amount Float? @db.DoublePrecision

  /// Coupon enable/start date.
  start_at DateTime @db.Timestamptz

  /// Coupon expiration/end date. Used for redemption window.
  end_at DateTime @db.Timestamptz

  /// Whether this coupon can be stacked/combined with others in a single
  /// purchase.
  stackable Boolean

  /// Record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Record update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp (null if not deleted).
  deleted_at DateTime? @db.Timestamptz

  //----
