  exposure_context String

  /// Variant or group id for bucket analysis ('A', 'B', 'control', etc.).
  group_assignment String

  /// Any additional metadata re: exposure type, test conditions, etc. (JSON).
  exposure_metadata String?

  /// Post-exposure response or outcome, for effect attribution. (e.g., click,
  /// conversion, bounce).
  result_outcome String?

  /// When the exposure occurred/logged.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shopping_mall_ai_customers? @relation(fields: [shopping_mall_ai_customer_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_ai_analytics_exposures_shopping_mall__e03ec04a")

  @@index([shopping_mall_ai_customer_id, created_at], map: "shopping_mall_ai_ai_analytics_exposures_shopping_mall__4fd95709")
  @@index([group_assignment, exposure_type], map: "shopping_mall_ai_ai_analytics_exposures_group_assignme_c606f7c8")
  @@index([exposure_context(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Records of all AI-driven (or heuristic) price optimization events, such
/// as suggestions, updates, campaign-triggered changes, and final
/// acceptance. Linked to time, product, channel, suggestion metadata, and
/// campaign context. Stores rationale, output, acceptance by operators, and
/// actual result (if known). Enables pricing science, campaign and model
/// tuning analytics, regulatory/compliance evidence.
///
/// @namespace AIBusinessLogic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_ai_price_optimizations {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Targeted product's {@link shopping_mall_ai_products.id}. References the
  /// product for which a price optimization event occurred.
  shopping_mall_ai_product_id String @db.Uuid

  /// Type/purpose of price optimization (e.g., 'AI_suggestion',
  /// 'manual_intervention', 'campaign', 'regulatory_correction').
  optimization_type String

  /// Channel/store/campaign context in which the optimization was performed
  /// (if multi-channel).
  channel_id String? @db.Uuid

  /// Original product price before optimization event.
  original_price Float @db.DoublePrecision

  /// Price suggested by AI/model/campaign, etc.
  suggested_price Float @db.DoublePrecision

  /// Final price actually applied (may differ from suggestion).
  final_price Float @db.DoublePrecision

  /// Serialized JSON documenting explanation/justification (regulatory, model,
  /// business) for optimization.
  decision_rationale String?

  /// Who/what accepted the suggestion (user id, automated, override, etc.).
  accepted_by String?

  /// Final observed result/impact (if measured) - e.g., conversion uplift,
  /// inventory move, complaint, rollback.
  result_outcome String?

  /// Timestamp of price optimization event.
