  product shopping_mall_ai_products @relation(fields: [shopping_mall_ai_product_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_ai_price_optimizations_shopping_mall__a053690e")

  @@index([shopping_mall_ai_product_id, created_at], map: "shopping_mall_ai_ai_price_optimizations_shopping_mall__47c24a8b")
  @@index([channel_id])
}

/// Specialized event/incident log capturing AI/heuristics-driven fraud/risk
/// scoring, intervention triggers (e.g., high-risk behaviors, payment
/// anomalies), and final actions (blocks, holds, escalations). Each row
/// records all primary signal properties, reasoning, action, and business
/// outcome. Used for risk analytics, compliance, fraud audits, and tuning of
/// AI risk models.
///
/// @namespace AIBusinessLogic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_fraud_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Optional involved customer's {@link shopping_mall_ai_customers.id}.
  shopping_mall_ai_customer_id String? @db.Uuid

  /// Order context (if relevant): {@link shopping_mall_ai_orders.id}.
  shopping_mall_ai_order_id String? @db.Uuid

  /// Type/category of fraud/risk indicator (e.g., 'multi_failed_login',
  /// 'stolen_card', 'geolocation_mismatch', etc.).
  fraud_signal_type String

  /// Quantitative fraud/risk score produced by AI/model/heuristic analysis.
  risk_score Float @db.DoublePrecision

  /// JSON-serialized input/behavior/data (IP, device, location, context, etc)
  /// for root cause/evidence.
  detail_json String?

  /// Action taken due to risk/fraud (e.g., 'soft_block', 'order_hold',
  /// 'user_alert', 'system_lock', etc.)
  intervention_type String?

  /// Result of fraud incident investigation (e.g., 'auto_resolved',
  /// 'escalated', 'cleared', 'blocked').
  final_outcome String?

  /// Timestamp of fraud detection/incident logged.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shopping_mall_ai_customers? @relation(fields: [shopping_mall_ai_customer_id], references: [id], onDelete: Cascade)
  order shopping_mall_ai_orders? @relation(fields: [shopping_mall_ai_order_id], references: [id], onDelete: Cascade)

  @@index([shopping_mall_ai_customer_id, created_at], map: "shopping_mall_ai_fraud_logs_shopping_mall_ai_customer__674021b9")
  @@index([shopping_mall_ai_order_id, created_at], map: "shopping_mall_ai_fraud_logs_shopping_mall_ai_order_id__d8c86a81")
  @@index([fraud_signal_type])
  @@index([detail_json(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Business-level, centralized incident log for exceptions, anomalies,
/// business rule violations, workflow failures, errors, or escalated
/// security/AI/fraud events not captured in domain-specific logs. Includes
/// context, trigger source, actors, impact, timeline, affected objects,
/// timeline/status, and resolution. Key for regulatory, operational, and
/// cross-domain audit/compliance.
///
/// @namespace AIBusinessLogic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_incident_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Associated customer if relevant. Optional link to {@link
  /// shopping_mall_ai_customers.id}.
  shopping_mall_ai_customer_id String? @db.Uuid

  /// Type/category of incident (e.g., 'AI_runtime_error', 'workflow_failure',
  /// 'policy_violation', 'escalated_support', 'security_flag', etc).
  incident_type String

  /// Serialized JSON context and trigger snapshot.
  incident_context String

  /// Current status of incident resolution (e.g., 'open', 'in_review',
  /// 'escalated', 'resolved', 'closed').
  status String

  /// Freeform impact classification (e.g., 'none', 'minor', 'business',
  /// 'data_loss', 'legal', etc).
  impact_level String

  /// Who/what triggered or is responsible for the incident (user id, system,
  /// AI, admin, etc).
  actor String

  /// Description/summary of resolution, mitigation, or update.
  resolution_summary String?

  /// When the incident was logged/created.
  created_at DateTime @db.Timestamptz

  /// When this incident record was last updated (status, resolution).
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shopping_mall_ai_customers? @relation(fields: [shopping_mall_ai_customer_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_incident_logs_shopping_mall_ai_custom_ed3e8675")

  @@index([shopping_mall_ai_customer_id], map: "shopping_mall_ai_incident_logs_shopping_mall_ai_custom_076cef5d")

  @@index([incident_type, created_at])
  @@index([status, impact_level])
  @@index([incident_context(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Long-term, full-fidelity audit log for all AI-driven and
/// business-critical actions/decisions/changes affecting major business
/// objects (user, product, order, payment, model, pricing, access, etc).
/// Immutable, actor/timestamp/event/target cross-referenced. Essential for
/// compliance, root-cause, incident investigation, and regulatory/legal
/// discovery.
///
/// @namespace AIBusinessLogic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_audit_trails {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Subject/affected customer, if any. References {@link
  /// shopping_mall_ai_customers.id}.
  shopping_mall_ai_customer_id String? @db.Uuid

  /// Type/category of audit event (e.g., 'ai_action', 'data_edit',
  /// 'access_grant', 'fraud_flag', 'model_update').
  event_type String

  /// What was affected by this event (e.g., 'product', 'order', 'user',
  /// 'model', 'pricing').
  target_type String

  /// Business identifier (UUID or business id) of the affected object.
  target_id String

  /// Who/what performed/triggered this action (user id, system, admin, AI).
  actor String

  /// Serialized (JSON) snapshot of object state before change/event, or null
  /// if not applicable.
  data_before String?

  /// Serialized (JSON) snapshot of object state after change/event, or null if
  /// not applicable.
  data_after String?

  /// Free-form business explanation of what happened, why (for compliance).
  ///
  description String?

  /// Audit event timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shopping_mall_ai_customers? @relation(fields: [shopping_mall_ai_customer_id], references: [id], onDelete: Cascade)

  @@index([shopping_mall_ai_customer_id])

  @@index([event_type, target_type, created_at], map: "shopping_mall_ai_audit_trails_event_type_target_type_c_e4a72359")
}

