  expired_at DateTime? @db.Timestamptz

  /// Last time the cart was changed or accessed (add/remove item, update
  /// quantity, etc.). Used for session management, expiration, and customer
  /// engagement analytics.
  last_activity_at DateTime @db.Timestamptz

  /// Timestamp when cart session was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when cart session was last updated (write lock, merge, edit,
  /// etc.).
  updated_at DateTime @db.Timestamptz

  /// When set, this cart has been logically deleted (soft delete for audit).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shopping_mall_ai_customers? @relation(fields: [shopping_mall_ai_customer_id], references: [id], onDelete: Cascade)

