  targetCart shopping_mall_ai_carts      @relation("shopping_mall_ai_cart_merge_logs_of_target_cart_id", fields: [target_cart_id], references: [id], onDelete: Cascade)
  customer   shopping_mall_ai_customers? @relation(fields: [shopping_mall_ai_customer_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_cart_merge_logs_shopping_mall_ai_cust_139d1941")

  @@index([source_cart_id])
  @@index([target_cart_id])
  @@index([shopping_mall_ai_customer_id], map: "shopping_mall_ai_cart_merge_logs_shopping_mall_ai_cust_4e7ff121")
