  order shopping_mall_ai_orders @relation(fields: [shopping_mall_ai_order_id], references: [id], onDelete: Cascade)

  shopping_mall_ai_refunds              shopping_mall_ai_refunds[]
  shopping_mall_ai_deposit_transactions shopping_mall_ai_deposit_transactions[]

  @@unique([payment_code])
  @@index([shopping_mall_ai_order_id])
  @@index([payment_method])
  @@index([status])
  @@index([created_at])
}

/// Refund request and transaction records, usually linked to an order or
/// payment. Includes full financial, actor, and reconciliation context.
/// Legally critical for chargebacks, compliance, and accounting. Supports
/// partial and full refund scenarios.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_refunds {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent order's {@link shopping_mall_ai_orders.id}.
  shopping_mall_ai_order_id String @db.Uuid

  /// Reference to related payment's {@link shopping_mall_ai_payments.id}, if
  /// refund is payment-based.
  shopping_mall_ai_payment_id String? @db.Uuid

  /// Unique refund transaction code, business-visible and externally auditable.
  refund_code String

  /// Status of the refund (requested, approved, rejected, completed, failed,
  /// cancelled).
  refund_status String

  /// Requested refund amount (may be less than total payment).
  requested_amount Float @db.DoublePrecision

  /// Approved refund amount (after admin/seller/auto adjustment), nullable
  /// until approved.
  approved_amount Float? @db.DoublePrecision

  /// 3-letter ISO currency code (KRW, USD, etc.).
  currency String

  /// Requester-provided reason for refund (user/admin entered).
  reason String?

  /// Timestamp when refund processing finalized (completed/rejected/failed).
  processed_at DateTime? @db.Timestamptz

  /// Refund record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Refund record updated timestamp.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  order   shopping_mall_ai_orders    @relation(fields: [shopping_mall_ai_order_id], references: [id], onDelete: Cascade)
  payment shopping_mall_ai_payments? @relation(fields: [shopping_mall_ai_payment_id], references: [id], onDelete: Cascade)

  shopping_mall_ai_deposit_transactions shopping_mall_ai_deposit_transactions[]

  @@unique([refund_code])
  @@index([shopping_mall_ai_payment_id])
  @@index([shopping_mall_ai_order_id])
  @@index([refund_status])
  @@index([created_at])
}

/// Return requests for order items/products. Represents customer- or
/// admin-initiated process for physical or digital return, mapped to orders
/// and optionally suborders/items. Tracked for full audit/auditability and
/// downstream refund, exchange, or after-service actions.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_returns {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Related order's {@link shopping_mall_ai_orders.id}.
  shopping_mall_ai_order_id String @db.Uuid

  /// Specific order item's {@link shopping_mall_ai_order_items.id} returned
  /// (nullable for full order/partial non-itemized return).
  shopping_mall_ai_order_item_id String? @db.Uuid

  /// Customer who initiated return ({@link shopping_mall_ai_customers.id}).
  shopping_mall_ai_customer_id String @db.Uuid

  /// Business-unique code identifying the return event (RMA).
  return_code String

  /// Customer/admin stated reason for the return.
  return_reason String

  /// Status of the return (requested, approved, received, refunded, rejected,
  /// completed).
  status String

  /// Timestamp when return was physically received (if physical goods).
  received_at DateTime? @db.Timestamptz

  /// Timestamp when return is resolved (refund issued or corrected, as per
  /// business flow).
  completed_at DateTime? @db.Timestamptz

  /// Return record created time.
  created_at DateTime @db.Timestamptz

  /// Return record updated time.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  order     shopping_mall_ai_orders       @relation(fields: [shopping_mall_ai_order_id], references: [id], onDelete: Cascade)
  orderItem shopping_mall_ai_order_items? @relation(fields: [shopping_mall_ai_order_item_id], references: [id], onDelete: Cascade)
  customer  shopping_mall_ai_customers    @relation(fields: [shopping_mall_ai_customer_id], references: [id], onDelete: Cascade)

  @@unique([return_code])
  @@index([shopping_mall_ai_order_item_id])
  @@index([shopping_mall_ai_customer_id])
  @@index([shopping_mall_ai_order_id])
  @@index([status])
}

/// After-Service (AS) requests for resolved or unresolved issues with
/// completed orders or items. Captures repair, exchange, complaint, special
/// investigation, or arbitration requests initiated by customer or raised by
/// the system/administrator. References orders, items, and actors for full
/// compliance, audit, and service workflow.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_after_service_requests {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Order's {@link shopping_mall_ai_orders.id} for which after-service was
  /// requested.
  shopping_mall_ai_order_id String @db.Uuid

  /// Order item ({@link shopping_mall_ai_order_items.id}), if AS applies to a
  /// specific item (nullable).
  shopping_mall_ai_order_item_id String? @db.Uuid

  /// Customer's ID ({@link shopping_mall_ai_customers.id}) who requested
  /// service.
  shopping_mall_ai_customer_id String @db.Uuid

  /// Seller's ID ({@link shopping_mall_ai_sellers.id}) responsible for AS if
  /// applicable.
  shopping_mall_ai_seller_id String? @db.Uuid

  /// Business-unique code identifying the after-service case.
  as_code String

  /// Nature of AS request (repair, exchange, complaint, investigation,
  /// arbitration, etc.).
  request_type String

  /// Current status of the AS request (requested, in_progress, completed,
  /// cancelled, denied, etc.).
  status String

  /// Customer-provided message/comment for service.
  contact_comment String?

  /// Internal note by admin/operator about case handling.
  admin_note String?

  /// AS request record created time.
  created_at DateTime @db.Timestamptz

  /// AS request record latest update time.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  order     shopping_mall_ai_orders       @relation(fields: [shopping_mall_ai_order_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_after_service_requests_shopping_mall__7e0e9afc")
  orderItem shopping_mall_ai_order_items? @relation(fields: [shopping_mall_ai_order_item_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_after_service_requests_shopping_mall__81d2395e")
  customer  shopping_mall_ai_customers    @relation(fields: [shopping_mall_ai_customer_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_after_service_requests_shopping_mall__9402f273")
  seller    shopping_mall_ai_sellers?     @relation(fields: [shopping_mall_ai_seller_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_after_service_requests_shopping_mall__f8ad632b")

  @@unique([as_code])
  @@index([shopping_mall_ai_order_item_id], map: "shopping_mall_ai_after_service_requests_shopping_mall__a0f28c40")
  @@index([shopping_mall_ai_customer_id], map: "shopping_mall_ai_after_service_requests_shopping_mall__af3308aa")
  @@index([shopping_mall_ai_seller_id], map: "shopping_mall_ai_after_service_requests_shopping_mall__f1beb73c")
  @@index([shopping_mall_ai_order_id], map: "shopping_mall_ai_after_service_requests_shopping_mall__c87376d6")
  @@index([request_type])
  @@index([status])
  @@index([contact_comment(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-06-discounts.prisma:
/// Core business table representing all platform and seller-issued coupons.
/// Defines coupon metadata, scope, state, issuance/redeem conditions, quota,
/// source campaign, stackability policy, and issuance controls. Tied to
/// issuance/redemption logs and parent campaigns. Supports both
/// product-level and cart-level discount logic. Links to campaign and
/// optionally a seller or platform administrator. Follows snapshot and
/// compliance/auditing patterns. Used extensively in coupon event flows.
///
/// @namespace Discounts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_coupons {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Source discount campaign's {@link
  /// shopping_mall_ai_discount_campaigns.id}. References the campaign that
  /// originated this coupon.
  shopping_mall_ai_discount_campaign_id String? @db.Uuid

  /// Coupon's issuing seller's {@link shopping_mall_ai_sellers.id}. Nullable
  /// if platform-wide or administrator coupon.
  shopping_mall_ai_seller_id String? @db.Uuid

  /// Coupon's issuing administrator's {@link
  /// shopping_mall_ai_administrators.id}. Nullable if seller coupon.
  shopping_mall_ai_administrator_id String? @db.Uuid

  /// Coupon code (unique per platform or per campaign, used for redemption).
  code String

  /// Coupon display title/purpose (e.g. Spring Sale 10%).
  title String

  /// Detailed description of the coupon offer or campaign.
  description String?

  /// Type of coupon (fixed, percent, free_shipping) for platform logic.
  /// Limited to allowed enums in business logic.
  type String

  /// Scope of coupon applicability (e.g., product, category, cart-wide).
  scope String

  /// Current state: issued, active, suspended, expired, redeemed, revoked,
  /// deleted. Life-cycle management for backend enforcement.
  status String

  /// Total number of coupon codes issued. Used for quota and tracking.
  issued_quantity Int @db.Integer

  /// Redemption quota per unique user. Used for eligibility checks.
  issued_per_user_quota Int @db.Integer

  /// Number of times this coupon has been redeemed. For quota and abuse
  /// monitoring.
  redeemed_quantity Int @db.Integer

  /// Cap (if any) on discount value this coupon can grant. Applies to
  /// percent/fixed.
  max_discount_amount Float? @db.DoublePrecision

  /// Minimum order value for coupon applicability.
  minimum_purchase_amount Float? @db.DoublePrecision

  /// Coupon enable/start date.
  start_at DateTime @db.Timestamptz

  /// Coupon expiration/end date. Used for redemption window.
  end_at DateTime @db.Timestamptz

  /// Whether this coupon can be stacked/combined with others in a single
  /// purchase.
  stackable Boolean

  /// Record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Record update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp (null if not deleted).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  discountCampaign shopping_mall_ai_discount_campaigns? @relation(fields: [shopping_mall_ai_discount_campaign_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_coupons_shopping_mall_ai_discount_cam_61eed141")
  seller           shopping_mall_ai_sellers?            @relation(fields: [shopping_mall_ai_seller_id], references: [id], onDelete: Cascade)
  administrator    shopping_mall_ai_administrators?     @relation(fields: [shopping_mall_ai_administrator_id], references: [id], onDelete: Cascade)

  shopping_mall_ai_coupon_issuance_logs   shopping_mall_ai_coupon_issuance_logs[]
  shopping_mall_ai_coupon_redemption_logs shopping_mall_ai_coupon_redemption_logs[]
  shopping_mall_ai_discount_rules         shopping_mall_ai_discount_rules[]
  shopping_mall_ai_mileage_transactions   shopping_mall_ai_mileage_transactions[]

  @@unique([code])
  @@index([shopping_mall_ai_discount_campaign_id], map: "shopping_mall_ai_coupons_shopping_mall_ai_discount_cam_1bc6e8b4")
  @@index([shopping_mall_ai_seller_id])
  @@index([shopping_mall_ai_administrator_id])
  @@index([scope])
  @@index([type])
  @@index([status])
  @@index([start_at])
  @@index([end_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Immutable audit log for every coupon issuance event, associating a coupon
/// to a particular user, including issuance method, status, quantities, and
/// actor. Used for quota, abuse, and compliance tracking. Enables detailed
/// analytics and abuse investigations. Never directly updated except for
/// rare administrative correction.
///
/// @namespace Discounts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_coupon_issuance_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Issued coupon's {@link shopping_mall_ai_coupons.id}.
  shopping_mall_ai_coupon_id String @db.Uuid

  /// Target customer's {@link shopping_mall_ai_customers.id} (recipient of the
  /// issued coupon).
  shopping_mall_ai_customer_id String @db.Uuid

  /// Issuance timestamp for audit.
  issued_at DateTime @db.Timestamptz

  /// IP address from which the issuance originated. For security and audit.
  issued_by_ip String?

  /// Issuance method (automatic, admin, seller, event, bulk, API, etc.).
  method String

  /// Number of coupons granted in this event. Typically 1, but supports bulk
  /// issuance.
  quantity Int @db.Integer

  /// Issuance-related admin/seller notes. Optional audit/context field.
  notes String?

  /// Record creation timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  coupon   shopping_mall_ai_coupons   @relation(fields: [shopping_mall_ai_coupon_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_coupon_issuance_logs_shopping_mall_ai_b69d0b55")
  customer shopping_mall_ai_customers @relation(fields: [shopping_mall_ai_customer_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_coupon_issuance_logs_shopping_mall_ai_39e895f7")

  @@unique([shopping_mall_ai_coupon_id, shopping_mall_ai_customer_id], map: "shopping_mall_ai_coupon_issuance_logs_shopping_mall_ai_bd4db697")
  @@index([shopping_mall_ai_customer_id], map: "shopping_mall_ai_coupon_issuance_logs_shopping_mall_ai_9ef0c21f")
  @@index([issued_at])
  @@index([method])
}

/// Immutable log for coupon redemption activity, linking issued coupon code
/// to a user, order, and redemption context. Enforces 1:1 relationship for
/// single-use coupons, supports multiple redemptions for multi-use where
/// business policy allows. Used for auditing, quota, fraud, and analytics.
/// All state changes are temporal, with immutable logs.
///
/// @namespace Discounts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_coupon_redemption_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Redeemed coupon's {@link shopping_mall_ai_coupons.id}.
  shopping_mall_ai_coupon_id String @db.Uuid

  /// The customer's {@link shopping_mall_ai_customers.id} who redeemed the
  /// coupon.
  shopping_mall_ai_customer_id String @db.Uuid

  /// Order's {@link shopping_mall_ai_orders.id} to which the coupon was
  /// applied.
  shopping_mall_ai_order_id String? @db.Uuid

  /// Date and time of coupon redemption.
  redeemed_at DateTime @db.Timestamptz

  /// Redemption result/state (success, failed, reversed, abuse_suspected,
  /// etc.).
  status String

  /// Discount value granted by this redemption event.
  discount_amount Float @db.DoublePrecision

  /// Redemption-related admin/automation notes.
  notes String?

  /// Record creation timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  coupon   shopping_mall_ai_coupons   @relation(fields: [shopping_mall_ai_coupon_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_coupon_redemption_logs_shopping_mall__7ce9703a")
  customer shopping_mall_ai_customers @relation(fields: [shopping_mall_ai_customer_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_coupon_redemption_logs_shopping_mall__0b575a21")
  order    shopping_mall_ai_orders?   @relation(fields: [shopping_mall_ai_order_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_coupon_redemption_logs_shopping_mall__f51ad8d0")

  @@unique([shopping_mall_ai_coupon_id, shopping_mall_ai_customer_id, shopping_mall_ai_order_id], map: "shopping_mall_ai_coupon_redemption_logs_shopping_mall__809935f4")
  @@index([shopping_mall_ai_customer_id], map: "shopping_mall_ai_coupon_redemption_logs_shopping_mall__2b8d65d4")
  @@index([shopping_mall_ai_order_id], map: "shopping_mall_ai_coupon_redemption_logs_shopping_mall__96fbc1ac")
  @@index([redeemed_at])
  @@index([status])
}

/// Master table for all discount and coupon campaigns (both platform and
/// seller-scope). Defines campaign metadata, rule sets, status, campaign
/// window, organizer, and analytic properties. Manages groupings of coupons
/// and core restrictions, such as issuance policy, eligible channels, quota,
/// and business objectives. Enables extensible marketing and multi-seller
/// campaign management.
///
/// @namespace Discounts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_discount_campaigns {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Campaign's owning administrator's {@link
  /// shopping_mall_ai_administrators.id}. Nullable if seller-driven.
  shopping_mall_ai_administrator_id String? @db.Uuid

  /// Campaign's owning seller's {@link shopping_mall_ai_sellers.id}. Nullable
  /// if platform only.
  shopping_mall_ai_seller_id String? @db.Uuid

  /// Campaign official name (unique within marketing domain).
  name String

  /// Detailed description of campaign purpose and target audience.
  description String?

  /// Current status: draft, active, ended, archived, suspended. Used for
  /// campaign workflow.
  status String

  /// Optional campaign budget for analytic/audit. Relevant for cost-based
  /// campaigns.
  budget_amount Float? @db.DoublePrecision

  /// Total maximum number of coupons issued by this campaign.
  total_coupon_quantity Int @db.Integer

  /// Campaign start date for timing logic.
  start_at DateTime @db.Timestamptz

  /// Campaign end/expiration date.
  end_at DateTime @db.Timestamptz

  /// Record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Record update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft delete/archival timestamp. Null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  administrator shopping_mall_ai_administrators? @relation(fields: [shopping_mall_ai_administrator_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_discount_campaigns_shopping_mall_ai_a_3d50afc2")
  seller        shopping_mall_ai_sellers?        @relation(fields: [shopping_mall_ai_seller_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_discount_campaigns_shopping_mall_ai_s_f73ac850")

  shopping_mall_ai_coupons        shopping_mall_ai_coupons[]
  shopping_mall_ai_discount_rules shopping_mall_ai_discount_rules[]

  @@unique([name])
  @@index([shopping_mall_ai_administrator_id], map: "shopping_mall_ai_discount_campaigns_shopping_mall_ai_a_ed48a82f")
  @@index([shopping_mall_ai_seller_id], map: "shopping_mall_ai_discount_campaigns_shopping_mall_ai_s_d642519b")
  @@index([status])
  @@index([start_at])
  @@index([end_at])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Extensible table defining discount/coupon eligibility, stacking, and
/// application business logic. Specifies product, category, channel,
/// section, quota, amount, and constraints, including exclusion and stacking
/// priority. Ties to campaigns and optionally coupons for granular
/// targeting. Used for automated discount engine rule evaluation and
/// enforcement.
///
/// @namespace Discounts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_ai_discount_rules {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Parent campaign's {@link shopping_mall_ai_discount_campaigns.id}.
  shopping_mall_ai_discount_campaign_id String @db.Uuid

  /// Related coupon's {@link shopping_mall_ai_coupons.id} if this rule maps to
  /// a specific coupon.
  shopping_mall_ai_coupon_id String? @db.Uuid

  /// Target section's {@link shopping_mall_ai_sections.id} for rule
  /// application. Optional granularity for complex sales.
  shopping_mall_ai_section_id String? @db.Uuid

  /// Target channel's {@link shopping_mall_ai_channels.id}. Nullable for
  /// platform-scope.
  shopping_mall_ai_channel_id String? @db.Uuid

  /// Target category's {@link shopping_mall_ai_categories.id}. Nullable if
  /// discounts are not category-specific.
  shopping_mall_ai_category_id String? @db.Uuid

  /// Target product's {@link shopping_mall_ai_products.id}. Nullable if rule
  /// applies more broadly.
  shopping_mall_ai_product_id String? @db.Uuid

  /// Type of rule (eligibility, exclusion, stacking, amount, quota, window,
  /// etc.). For discount engine logic segmentation.
  rule_type String

  /// How the rule is applied (product, cart, channel, etc.).
  application_type String

  /// Type of amount (fixed, percent, free_shipping, etc.).
  amount_type String

  /// Discount value specified by the rule (fixed value or percent as context
  /// implies).
  amount_value Float? @db.DoublePrecision

  /// Minimum order amount required for rule validity.
  minimum_purchase_amount Float? @db.DoublePrecision

  /// Maximum cap on discount granted by this rule. Applies to percent rules.
  maximum_discount_amount Float? @db.DoublePrecision

  /// Order precedence for stacking enforcement/priority.
  stack_priority Int @db.Integer

  /// Redemption quota limit for this rule.
  quota Int? @db.Integer

  /// Rule activation/start datetime.
  start_at DateTime @db.Timestamptz

  /// Rule deactivation/end datetime.
  end_at DateTime @db.Timestamptz

  /// Record creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Record update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp (null if active or never deleted).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  discountCampaign shopping_mall_ai_discount_campaigns @relation(fields: [shopping_mall_ai_discount_campaign_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_discount_rules_shopping_mall_ai_disco_8f5ff557")
  coupon           shopping_mall_ai_coupons?           @relation(fields: [shopping_mall_ai_coupon_id], references: [id], onDelete: Cascade)
  section          shopping_mall_ai_sections?          @relation(fields: [shopping_mall_ai_section_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_discount_rules_shopping_mall_ai_secti_eb1e71a7")
  channel          shopping_mall_ai_channels?          @relation(fields: [shopping_mall_ai_channel_id], references: [id], onDelete: Cascade, map: "shopping_mall_ai_discount_rules_shopping_mall_ai_chann_7d9239a8")
